import { html } from 'common-tags'

export const registryItem = {
  type: 'registry:ui',
  name: 'collapsible',
  title: 'Collapsible',

  description: html`
    An interactive component which expands/collapses a panel.

    References:
    - Headless API: https://ark-ui.com/docs/components/collapsible
    - shadcn/ui: https://ui.shadcn.com/docs/components/collapsible
  `,

  dependencies: [
    '@ark-ui/vue',
    '@vueuse/core',
  ],

  cssVars: {
    theme: {
      '--animate-collapsible-down': 'collapsible-down 0.25s ease-out',
      '--animate-collapsible-up': 'collapsible-up 0.25s ease-out',
    },
  },

  css: {
    '@keyframes collapsible-down': {
      from: { height: '0' },
      to: { height: 'var(--height)' },
    },
    '@keyframes collapsible-up': {
      from: { height: 'var(--height)' },
      to: { height: '0' },
    },
  },
}

export default registryItem

import type { Meta, StoryObj } from '@storybook/vue3-vite'

import { html } from 'common-tags'

import { Collapsible } from '@/components/ui/collapsible'
import { registryItem } from './_registry'

import { docsRoot } from '../../../_helpers/docs-root'
import CollapsibleDefaultStory from './CollapsibleDefaultStory.vue'
import CollapsibleDefaultSource from './CollapsibleDefaultStory.vue?raw'

const meta: Meta<typeof Collapsible.Root> = {
  title: 'Components/UI/Collapsible',
  component: docsRoot(Collapsible.Root, 'Collapsible.Root'),
  subcomponents: {
    'Collapsible.Trigger': Collapsible.Trigger,
    'Collapsible.Content': Collapsible.Content,
  },
  tags: ['autodocs'],

  parameters: {
    docs: {
      description: {
        component: registryItem.description,
      },
    },
  },
}

export default meta
type Story = StoryObj<typeof meta>

export const Default: Story = {
  parameters: {
    docs: {
      source: {
        code: CollapsibleDefaultSource,
      },
    },
  },

  render: args => ({
    components: { CollapsibleDefaultStory },

    setup() {
      return { args }
    },

    template: html`
      <CollapsibleDefaultStory v-bind="args" />
    `,
  }),
}
